"use strict";
/* Harder forms (about 500 to 620 level). All items are original.
   Uses helpers from reading.js (rq) and listening.js (dlg, lq). Correct answers are listed first for A-type and R/L items; the app shuffles them. */

var S_AGR="Matching verbs to subjects", S_TEN="Verb tenses", S_WF="Describing words and action words", S_CNT="Counting words",
    S_LINK="Linking words", S_CMP="Comparing things", S_IF="If sentences", S_ING="-ing or to + verb", S_WHO="Who, which, whose",
    S_LST="Lists that match", S_SUG="The 'suggest that' pattern", S_FLIP="Flipped word order", S_EMB="Questions inside sentences", S_OPEN="Opening -ing phrases";
function sA(topic,stem,correct,wrongs,why){return {part:"A",topic:topic,stem:stem,opts:[correct].concat(wrongs),ans:0,why:why};}
function sB(topic,text,ans,why,fix){return {part:"B",topic:topic,text:text,ans:ans,why:why,fix:fix};}

/* ================= STRUCTURE: HARDER FORM ================= */
var TEST_H=[
sA(S_IF,"Had the committee been informed earlier, it ______ the proposal.","would have rejected",["would reject","had rejected","rejected"],"'Had the committee been informed' means 'If the committee had been informed'. This is about an imaginary past, so the other part needs 'would have + verb'."),
sA(S_FLIP,"Only after the data had been checked ______ the results.","did the team announce",["the team announced","the team did announce","announced the team"],"'Only after...' at the start of a sentence flips the order in the main part: did + subject + plain verb."),
sA(S_AGR,"The professor, along with her graduate students, ______ presenting at the conference next week.","is",["are","were","have been"],"The subject is 'the professor' (one person). 'Along with her graduate students' is extra information and does not change the verb."),
sA(S_CMP,"The more carefully the experiment is designed, ______ are the results.","the more reliable",["more reliable","the most reliable","reliable more"],"The pattern is 'the more... the more...'. So: 'the more carefully..., the more reliable'."),
sA(S_WHO,"The researchers, ______ funding had been cut, continued the project on their own.","whose",["who","whom","which"],"'Whose' means 'belonging to' and comes before a noun. The funding belonged to the researchers."),
sA(S_SUG,"She suggested that the meeting ______ until the following week.","be postponed",["is postponed","was postponed","would postpone"],"After 'suggest that', use the plain verb. For a passive sentence this is 'be + verb': 'be postponed'."),
sA(S_LINK,"______ the storm, the ferry service was suspended.","Due to",["Because","Although","Despite"],"'Due to' is followed by a noun (the storm) and gives a reason. 'Because' needs a full sentence, 'although' shows contrast, and 'despite' shows contrast too."),
sA(S_FLIP,"Not only ______ the exam, but she also received the highest score in her class.","did she pass",["she passed","she did pass","passed she"],"'Not only' at the start flips the order: did + subject + plain verb. So: 'Not only did she pass'."),
sA(S_ING,"The ancient city is believed ______ by an earthquake around 500 BC.","to have been destroyed",["to destroy","to have destroyed","being destroyed"],"The city did not destroy anything. It was destroyed, in the past. So you need 'to have been destroyed'."),
sA(S_AGR,"Neither the teachers nor the principal ______ aware of the schedule change.","is",["are","were","have been"],"With 'neither... nor', the verb matches the closer subject. 'The principal' is one person, so 'is'."),
sA(S_ING,"Students are advised ______ their assignments before the deadline.","to submit",["submitting","submit","to submitting"],"'Advise' is followed by 'to + verb' when it is used with a person: 'advised to submit'."),
sA(S_TEN,"By the time the rescue team arrived, the climbers ______ for nearly two days.","had been waiting",["were waiting","have waited","wait"],"The waiting started before the team arrived and continued up to that time. For this, use 'had been + -ing'."),
sA(S_EMB,"The measurements were different from ______ the team had expected.","what",["that","which","those"],"'What the team had expected' works like a noun: it means 'the thing the team expected'. The other words cannot do this job here."),
sA(S_EMB,"______ the speed of light is constant is a fundamental principle of physics.","That",["What","Which","It"],"'That the speed of light is constant' is a whole idea used as the subject of the sentence. 'That' introduces it."),
sA(S_OPEN,"Working late into the night, ______.","Maria finished the report",["the report was finished by Maria","the report seemed finished","finishing was Maria's goal"],"The person doing the action in the opening phrase must come right after the comma. Who was working late? Maria."),

sB(S_AGR,"{A:The majority} of the students {B:in the survey} {C:was} {D:satisfied} with the new schedule.",2,"'The majority of the students' means many students, so the verb is plural: 'were'.","The majority of the students in the survey were satisfied with the new schedule."),
sB(S_FLIP,"{A:Scarcely} {B:had} the lecture {C:begun} {D:than} students started leaving.",3,"'Scarcely' goes with 'when', not 'than'. ('No sooner' is the one that goes with 'than'.)","Scarcely had the lecture begun when students started leaving."),
sB(S_WHO,"The scientist {A:who} discovered the compound, {B:whom} {C:many} believed would win the prize, {D:declined} the award.",1,"'Many believed would win' means 'many believed that he would win'. The missing word is a subject, so it must be 'who', not 'whom'.","The scientist who discovered the compound, who many believed would win the prize, declined the award."),
sB(S_AGR,"{A:Despite} the fact {B:that} the project {C:was} expensive, it {D:were} completed on time.",3,"'It' is one thing, so the verb is 'was'.","Despite the fact that the project was expensive, it was completed on time."),
sB(S_SUG,"It is {A:essential} that the contract {B:is} {C:signed} {D:by Friday}.",1,"After 'it is essential that', use the plain form of the verb: 'be signed'.","It is essential that the contract be signed by Friday."),
sB(S_ING,"{A:In order} {B:to} {C:avoid to be late}, {D:she left early}.",2,"After 'avoid', use the -ing form: 'avoid being late'.","In order to avoid being late, she left early."),
sB(S_CNT,"The {A:amount} of {B:applications} {C:has} {D:increased}.",0,"Applications can be counted, so use 'number of'. 'Amount of' is for things you can't count.","The number of applications has increased."),
sB(S_IF,"{A:Had} she {B:knew} the answer, she {C:would have} {D:raised} her hand.",1,"After 'had' in this pattern, use the verb form 'known' (had + known).","Had she known the answer, she would have raised her hand."),
sB(S_FLIP,"{A:Rarely teachers} {B:give} {C:such detailed} {D:feedback}.",0,"'Rarely' at the start of a sentence flips the order: 'Rarely do teachers give...'.","Rarely do teachers give such detailed feedback."),
sB(S_AGR,"{A:Each} of the {B:new} {C:students} {D:need} a library card.",3,"'Each' means each one separately, so the verb is singular: 'needs'.","Each of the new students needs a library card."),
sB(S_CMP,"The {A:higher} the temperature, {B:more quickly} the molecules {C:move} {D:randomly}.",1,"The pattern is 'the + comparative, the + comparative'. You need 'the' before 'more quickly'.","The higher the temperature, the more quickly the molecules move randomly."),
sB(S_AGR,"She is {A:one of the} researchers who {B:has} {C:published} {D:widely} on the topic.",1,"'Who' stands for 'researchers' (many), so the verb is plural: 'have published'.","She is one of the researchers who have published widely on the topic."),
sB(S_LST,"The new manager is {A:both} {B:experienced} {C:and} {D:has a lot of energy}.",3,"After 'both... and', both sides must have the same form. 'Experienced' is a describing word, so the other side should be too: 'energetic'.","The new manager is both experienced and energetic."),
sB(S_FLIP,"{A:Not until} the 1990s {B:did} the Internet {C:became} {D:widely available}.",2,"After 'did', use the plain verb: 'become'.","Not until the 1990s did the Internet become widely available."),
sB(S_OPEN,"{A:Having been} {B:warned} about the storm, {C:the flight} {D:was delayed}.",2,"The person doing the action in the opening phrase must come right after the comma. A flight cannot be warned. A person or company must follow the comma.","Having been warned about the storm, the airline delayed the flight."),
sB(S_WF,"{A:Children's sleeps habits} {B:strongly} {C:affect} {D:their grades}, the report suggests.",0,"When a noun describes another noun, it stays singular: 'sleep habits', not 'sleeps habits'.","Children's sleep habits strongly affect their grades, the report suggests."),
sB(S_AGR,"{A:The equipment} {B:in the} {C:new laboratories} {D:are} very expensive.",3,"The subject is 'equipment', which cannot be counted and is singular. Ignore 'in the new laboratories'. So: 'is'.","The equipment in the new laboratories is very expensive."),
sB(S_IF,"{A:If} the weather {B:will be} {C:good} tomorrow, we {D:will have} a picnic.",1,"In the 'if' part of a possible-future sentence, use the present form: 'if the weather is good'.","If the weather is good tomorrow, we will have a picnic."),
sB(S_SUG,"The professor {A:asked} {B:that} {C:each student} {D:to bring} a dictionary.",3,"After 'asked that', use the plain verb with no 'to': 'each student bring'.","The professor asked that each student bring a dictionary."),
sB(S_AGR,"{A:Whether} the plan will succeed {B:depend} {C:on} {D:funding}.",1,"The whole phrase 'whether the plan will succeed' is one idea, so the verb is singular: 'depends'.","Whether the plan will succeed depends on funding."),
sB(S_WF,"The research was conducted over {A:a three years} {B:period} and {C:involved} {D:200 participants}.",0,"When a number joins a noun to describe another noun, the noun stays singular: 'a three-year period'.","The research was conducted over a three-year period and involved 200 participants."),
sB(S_FLIP,"She {A:could} {B:not} {C:hardly} {D:believe} her luck.",1,"'Hardly' already means 'almost not'. Don't add 'not' as well. Say 'could hardly believe'.","She could hardly believe her luck."),
sB(S_AGR,"{A:Compared} {B:with} last year, the number of tourists {C:are} {D:much higher}.",2,"'The number of' is singular, so the verb is 'is'.","Compared with last year, the number of tourists is much higher."),
sB(S_AGR,"Despite {A:it's} {B:high price}, the {C:phone} sold {D:well}.",0,"'It's' means 'it is'. To show possession, use 'its': 'its high price'.","Despite its high price, the phone sold well."),
sB(S_LINK,"The two {A:candidates} {B:differ} {C:in their approach on} {D:education}.",2,"The common phrase is 'approach to' something, not 'approach on'.","The two candidates differ in their approach to education.")
];

/* ================= READING: HARDER FORM ================= */
var RPASS_H=[
{title:"Passage 1: The Placebo Effect",paras:[
"A placebo is a treatment that has no active medical ingredient, such as a sugar pill or an injection of salt water. For decades, doctors used placebos mainly as a tool in research: to test whether a new drug works, one group of patients receives the drug and another receives a placebo, and the results are compared. Surprisingly, patients who take placebos often report real improvements, a [[phenomenon]] known as the placebo effect.",
"Researchers believe the effect depends largely on expectation. When people believe that a treatment will help them, their brains may release natural chemicals that reduce pain or stress. Brain scans have shown that [[this change]] is not imaginary; areas of the brain involved in pain respond differently when a person expects relief. The effect is strongest for conditions that are partly shaped by perception, such as pain, nausea, and fatigue, and it is much weaker or absent for conditions like broken bones or infections.",
"The details of a treatment can also change the result. Studies suggest that larger pills often work better than small ones, that injections feel more powerful than tablets, and that a brand-name label can raise expectations. A caring doctor who explains the treatment warmly may produce better outcomes than one who seems rushed, even when both prescribe the same thing.",
"These findings have raised an ethical question. Giving patients a [[sham]] treatment without telling them seems dishonest, yet the benefits can be real. Some researchers have therefore tested 'open' placebos, in which patients are told that the pill contains no medicine. In a few small studies, patients still improved, although scientists caution that the results need to be confirmed with larger groups before doctors rely on them."
]},
{title:"Passage 2: Urban Heat Islands",paras:[
"Cities are often several degrees warmer than the countryside around them, especially at night. This difference, known as the urban heat island effect, [[arises]] mainly because of the materials from which cities are built. Dark roofs and pavements absorb sunlight during the day and release the stored heat slowly after sunset, while buildings and roads cover the soil and plants that would otherwise cool the air through evaporation.",
"The layout of a city makes matters worse. Tall buildings packed close together trap heat between them and block breezes that might carry it away. In addition, cars, air conditioners, and factories release heat directly into the air. On a hot summer day, these factors can raise temperatures in a dense neighborhood by several degrees compared with a nearby park.",
"The consequences go beyond discomfort. Higher temperatures increase electricity demand because people run air conditioners more often, [[which]] in turn produces more heat and more pollution. Heat waves are also dangerous for the elderly and for people without cooling at home, and hospitals typically see more patients on extremely hot days.",
"Planners have several options. Light-colored roofs reflect more sunlight, and planting trees provides shade and releases water vapor that cools the air. Some cities have created green corridors that allow breezes to move through crowded districts. None of these measures is a complete solution, but together they can lower temperatures [[noticeably]]. Importantly, the need is often greatest in poorer neighborhoods, which usually have the fewest trees."
]},
{title:"Passage 3: The Silk Road",paras:[
"The Silk Road was not a single road but a network of trade routes that connected China with the Mediterranean world for more than a thousand years. It acquired its name in the nineteenth century, long after its busiest period, because silk was among the most valuable goods that traveled westward. Few merchants, however, journeyed the whole distance. Instead, goods passed from trader to trader, gaining value at every stage.",
"Silk was far from the only [[commodity]]. Caravans carried spices, tea, and porcelain from East to West, and returned with glassware, gold, and horses. Camels, which can travel long distances with little water, made it possible to cross the deserts of Central Asia. Along the way, oasis towns grew wealthy by supplying travelers with food, water, and lodging, and some became important centers of learning.",
"Perhaps the most lasting exchange was not material but intellectual. Religions such as Buddhism spread eastward from India along these routes, and artistic styles, scientific ideas, and technologies traveled with [[them]]. Paper and printing, both developed in China, eventually reached Europe, where they transformed how knowledge was recorded. Diseases traveled too; many historians argue that the plague that [[devastated]] Europe in the fourteenth century spread, in part, along trade routes.",
"The network declined gradually. When sea routes between Europe and Asia became safer and cheaper, ships could carry more goods than caravans, and overland trade lost much of its importance. Nevertheless, the idea of the Silk Road has endured. Today, several governments use the name to describe new transport and trade projects, hoping to recall a time when distant peoples traded and learned from one another."
]},
{title:"Passage 4: Light in the Deep Sea",paras:[
"Below about a thousand meters, sunlight no longer reaches the ocean, and the water is almost completely dark. Yet this darkness is not empty: many deep-sea animals produce their own light through a chemical reaction called bioluminescence. Scientists estimate that a large proportion of animals living in the deep ocean can do so, making light one of the most important tools for survival there.",
"Light serves different purposes for different species. The anglerfish dangles a glowing [[lure]] in front of its mouth, attracting small fish that mistake it for food. Some squid release a cloud of glowing liquid instead of ink, confusing predators while the squid escapes. Others use light for camouflage: by glowing faintly on their undersides, [[they]] match the dim light from above, so predators looking up cannot see their outlines against the water.",
"Light is also used to find partners. Certain species of deep-sea shrimp and fish produce patterns of flashes that are [[unique]] to their species, allowing individuals to recognize one another in the dark. Scientists believe these signals may have evolved separately many times, which suggests that producing light is a relatively easy trait for evolution to create.",
"Studying these animals is difficult. Most die when brought to the surface, because of the change in pressure and temperature, and bright lights used by research vehicles can frighten them or disturb their behavior. Recently, researchers have begun using very dim red lights, which most deep-sea creatures cannot see, and cameras sensitive enough to record the faint glow of animals in their natural habitat."
]},
{title:"Passage 5: Nudges and Default Choices",paras:[
"Economists once assumed that people make decisions by carefully comparing costs and benefits. Over the past few decades, however, research in behavioral economics has shown that choices are often shaped by small features of how options are presented. A 'nudge' is any change in presentation that [[predictably]] influences behavior without forbidding any option or significantly changing incentives.",
"One of the best-known examples involves default options. In many countries, citizens must actively sign up to become organ donors, and registration rates are low. In countries where donation is the default and people must opt out, registration rates are far higher, even though people in both systems are free to choose either way. Similarly, when companies automatically enroll employees in retirement savings plans, many more workers save, because most people stick with the arrangement they are given rather than make an active change.",
"Why are defaults so powerful? Researchers point to several reasons. Changing a default requires effort, and effort feels costly when a decision seems complicated. Defaults may also be read as recommendations: people assume the option chosen for [[them]] is the one most others prefer. Finally, people tend to dislike losing what they already have, so abandoning the default can feel like a loss.",
"Critics raise concerns. They argue that nudges, however gentle, still steer people toward outcomes chosen by someone else, and that the chooser may not share the person's goals. Supporters respond that every presentation of choices influences people in some way, so the real question is not whether to nudge but who designs the nudge and how openly. Most agree that nudges work best when their purpose is [[transparent]] and when people can easily choose differently."
]}
];

